struct LevelBook {
    std::vector<uint32_t> bid, ask;
    explicit LevelBook(std::size_t depth) : bid(depth, 0), ask(depth, 0) {}

    // Returns true only on a true underflow — a REMOVE for MORE shares than the
    // level holds — which clamps to zero (the phantom-depth rule). Exact
    // removal (shares == level) empties the level without an underflow, matching
    // OrderBookFlat::_remove_level's `if (lv <= shares) lv = 0;` for the value
    // while distinguishing the error pulse from a clean emptying.
    bool apply(int op, int side, std::size_t idx, uint32_t shares) {
        std::vector<uint32_t>& lv = (side == SIDE_BID) ? bid : ask;
        if (op == OP_ADD) {
            lv[idx] += shares;
            return false;
        }
        if (shares > lv[idx]) {
            lv[idx] = 0;
            return true;  // underflow clamp
        }
        lv[idx] -= shares;
        return false;
    }

    // best_bid: highest occupied index; best_ask: lowest occupied index.
    bool best(int side, std::size_t& idx, uint32_t& shares) const {
        const std::vector<uint32_t>& lv = (side == SIDE_BID) ? bid : ask;
        if (side == SIDE_BID) {
            for (std::size_t i = lv.size(); i-- > 0;)
                if (lv[i] > 0) { idx = i; shares = lv[i]; return true; }
        } else {
            for (std::size_t i = 0; i < lv.size(); ++i)
                if (lv[i] > 0) { idx = i; shares = lv[i]; return true; }
        }
        idx = 0;
        shares = 0;
        return false;
    }
};

struct Op {
    int op, side;
    uint32_t index, shares;
};

void write_csv(std::FILE* out, std::size_t depth, const std::vector<Op>& ops) {
    std::fprintf(out, "# flat_book_golden schema=1 depth=%zu shares_w=32\n", depth);
    std::fprintf(out,
        "op,side,index,shares,bid_valid,bid_index,bid_shares,"
        "ask_valid,ask_index,ask_shares,clamp\n");
    LevelBook book(depth);
    for (const Op& o : ops) {
        const bool clamp = book.apply(o.op, o.side, o.index, o.shares);
        std::size_t bidx = 0, aidx = 0;
        uint32_t bsh = 0, ash = 0;
        const bool bv = book.best(SIDE_BID, bidx, bsh);
        const bool av = book.best(SIDE_ASK, aidx, ash);
        std::fprintf(out, "%d,%d,%u,%u,%d,%zu,%u,%d,%zu,%u,%d\n",
                     o.op, o.side, o.index, o.shares,
                     bv ? 1 : 0, bidx, bsh, av ? 1 : 0, aidx, ash, clamp ? 1 : 0);
    }
}

// Hand-written sequence hitting the contract's corners: boundary indexes 0 and
// depth-1, clamp-at-zero, removing the current best (best moves), and emptying
// a side (best_valid deasserts).
std::vector<Op> edge_ops(std::size_t depth) {
    // Level indexes are derived from depth so the sequence stays in-bounds for
    // any depth the tool accepts in edge mode (>= 8, enforced in main). Earlier
    // hardcoded indexes (100/200/350/400) overran the level arrays whenever
    // depth was small — a silent heap overflow. The interior levels are spaced
    // 0 < b_lo < b_hi < a_mid < a_hi < depth-1 so best-of-side still moves up
    // (bid) and down (ask), and both boundaries (0 and depth-1) are exercised.
    const uint32_t hi    = static_cast<uint32_t>(depth - 1);
    const uint32_t b_lo  = static_cast<uint32_t>(depth / 8);
    const uint32_t b_hi  = static_cast<uint32_t>(depth / 4);
    const uint32_t a_mid = static_cast<uint32_t>(3 * depth / 8);
    const uint32_t a_hi  = static_cast<uint32_t>(depth / 2);
    return {
        {OP_ADD, SIDE_BID, b_lo, 500},        // bid best = b_lo
        {OP_ADD, SIDE_BID, b_hi, 300},        // bid best moves up to b_hi
        {OP_ADD, SIDE_BID, 0, 111},           // boundary index 0 (not best)
        {OP_ADD, SIDE_ASK, a_hi, 250},        // ask best = a_hi
        {OP_ADD, SIDE_ASK, hi, 999},          // boundary index depth-1
        {OP_ADD, SIDE_ASK, a_mid, 700},       // ask best moves down to a_mid
        {OP_REMOVE, SIDE_ASK, a_mid, 700},    // remove best ask -> back to a_hi
        {OP_REMOVE, SIDE_BID, b_hi, 1000},    // over-remove best bid -> clamp, best back to b_lo
        {OP_REMOVE, SIDE_BID, b_lo, 500},     // empty b_lo
        {OP_REMOVE, SIDE_BID, 0, 111},        // empty side -> bid best invalid
        {OP_REMOVE, SIDE_ASK, a_hi, 250},     // empty a_hi -> ask best = depth-1
        {OP_REMOVE, SIDE_ASK, hi, 999},       // empty side -> ask best invalid
    };
}

std::vector<Op> random_ops(std::size_t depth, uint32_t seed, int n) {
    std::mt19937 rng(seed);
    std::uniform_int_distribution<int> side(0, 1);
    std::uniform_int_distribution<int> op(0, 1);
    std::uniform_int_distribution<uint32_t> idx(0, static_cast<uint32_t>(depth - 1));
    std::uniform_int_distribution<uint32_t> sh(1, 1000);
    std::vector<Op> ops;
    ops.reserve(n);
    for (int i = 0; i < n; ++i)
        ops.push_back({op(rng), side(rng), idx(rng), sh(rng)});
    return ops;
}

}  // namespace

int main(int argc, char** argv) {
    if (argc < 4) {
        std::fprintf(stderr,
            "usage: %s <edge|random> <depth> <out.csv> [seed]\n", argv[0]);
        return 2;
    }
    const std::string mode = argv[1];
    const std::size_t depth = std::strtoul(argv[2], nullptr, 10);
    const char* out_path = argv[3];
    const uint32_t seed = argc >= 5 ? std::strtoul(argv[4], nullptr, 10) : 12345u;
    if (depth < 2 || depth > 4096) {
        std::fprintf(stderr, "depth must be in [2, 4096]\n");
        return 2;
    }

    std::vector<Op> ops;
    if (mode == "edge") {
        ops = edge_ops(depth);
    } else if (mode == "random") {
        ops = random_ops(depth, seed, 10000);
    } else {
        std::fprintf(stderr, "unknown mode '%s' (edge|random)\n", mode.c_str());
        return 2;
    }

    std::FILE* out = std::fopen(out_path, "wb");
    if (!out) {
        std::fprintf(stderr, "cannot open %s for writing\n", out_path);
        return 2;
    }
    write_csv(out, depth, ops);
    std::fclose(out);
    std::fprintf(stderr, "wrote %zu ops (%s, depth=%zu) to %s\n",
                 ops.size(), mode.c_str(), depth, out_path);
    return 0;
}

-- flat_book_tb.vhd — file-driven testbench.
-- Plan: .claude/plans/vhdl-flat-book.md.
--
-- Reads the golden CSV produced by cpp/itch/golden_vectors_main.cpp (schema
-- version asserted from the header comment before any op runs), applies one op
-- per clock cycle, asserts level best-of-book outputs and clamp pulses match
-- the C++ oracle exactly, and reports total cycles. GHDL exits nonzero on any
-- assertion failure (severity failure) — that exit code IS the parity test
-- consumed by tests/test_vhdl_flat_book.py; a clean run ends with std.env.finish
-- (exit 0). The VECTORS generic is the CSV path; DEPTH matches the entity.

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

use std.textio.all;
use std.env.all;

entity flat_book_tb is
  generic (
    VECTORS : string  := "golden.csv";
    DEPTH   : positive := 4096
  );
end entity flat_book_tb;

architecture sim of flat_book_tb is
  constant SHARES_W : positive := 32;
  constant HALF     : time := 5 ns;

  signal clk       : std_logic := '0';
  signal rst       : std_logic := '0';
  signal op_valid  : std_logic := '0';
  signal op_kind   : std_logic := '0';
  signal op_side   : std_logic := '0';
  signal op_index  : unsigned(11 downto 0) := (others => '0');
  signal op_shares : unsigned(SHARES_W - 1 downto 0) := (others => '0');

  signal best_bid_valid  : std_logic;
  signal best_bid_index  : unsigned(11 downto 0);
  signal best_bid_shares : unsigned(SHARES_W - 1 downto 0);
  signal best_ask_valid  : std_logic;
  signal best_ask_index  : unsigned(11 downto 0);
  signal best_ask_shares : unsigned(SHARES_W - 1 downto 0);
  signal err_underflow_clamped : std_logic;

  -- Read one comma-separated integer, then consume the trailing separator
  -- (which is absent on the final field — that read simply fails harmlessly).
  procedure read_csv_int(variable l : inout line; variable val : out integer) is
    variable ch : character;
    variable ok : boolean;
  begin
    read(l, val, ok);
    assert ok report "golden CSV: expected an integer field" severity failure;
    read(l, ch, ok);  -- consume ',' if present; end-of-line -> ok=false (fine)
  end procedure;
begin
  dut : entity work.flat_book
    generic map (DEPTH => DEPTH, SHARES_W => SHARES_W)
    port map (
      clk => clk, rst => rst,
      op_valid => op_valid, op_kind => op_kind, op_side => op_side,
      op_index => op_index, op_shares => op_shares,
      best_bid_valid => best_bid_valid, best_bid_index => best_bid_index,
      best_bid_shares => best_bid_shares,
      best_ask_valid => best_ask_valid, best_ask_index => best_ask_index,
      best_ask_shares => best_ask_shares,
      err_underflow_clamped => err_underflow_clamped
    );

  stim : process
    file f          : text;
    variable status : file_open_status;
    variable l      : line;
    variable op, side, index, shares : integer;
    variable ebv, ebi, ebs, eav, eai, eas, eclamp : integer;
    variable cycles : integer := 0;
    constant HDR    : string := "# flat_book_golden schema=1";
  begin
    file_open(status, f, VECTORS, read_mode);
    assert status = open_ok
      report "cannot open golden vectors: " & VECTORS severity failure;

    -- One reset cycle.
    rst <= '1'; op_valid <= '0';
    clk <= '0'; wait for HALF;
    clk <= '1'; wait for HALF;
    rst <= '0'; clk <= '0'; wait for HALF;

    -- Header: assert the schema comment, then skip the column-name line.
    readline(f, l);
    assert l'length >= HDR'length and l.all(1 to HDR'length) = HDR
      report "golden CSV schema mismatch (expected '" & HDR & "')" severity failure;
    readline(f, l);

    while not endfile(f) loop
      readline(f, l);
      next when l'length = 0;
      read_csv_int(l, op);   read_csv_int(l, side);
      read_csv_int(l, index); read_csv_int(l, shares);
      read_csv_int(l, ebv);  read_csv_int(l, ebi); read_csv_int(l, ebs);
      read_csv_int(l, eav);  read_csv_int(l, eai); read_csv_int(l, eas);
      read_csv_int(l, eclamp);

      -- Drive the op, then pulse the clock (rising edge applies it).
      op_valid  <= '1';
      op_kind   <= '1' when op = 1 else '0';
      op_side   <= '1' when side = 1 else '0';
      op_index  <= to_unsigned(index, 12);
      op_shares <= to_unsigned(shares, SHARES_W);
      clk <= '0'; wait for HALF;
      clk <= '1'; wait for HALF;   -- rising edge + output settle

      assert (best_bid_valid = '1') = (ebv = 1)
        report "bid_valid mismatch at op " & integer'image(cycles) severity failure;
      assert to_integer(best_bid_index) = ebi
        report "bid_index mismatch at op " & integer'image(cycles) severity failure;
      assert to_integer(best_bid_shares) = ebs
        report "bid_shares mismatch at op " & integer'image(cycles) severity failure;
      assert (best_ask_valid = '1') = (eav = 1)
        report "ask_valid mismatch at op " & integer'image(cycles) severity failure;
      assert to_integer(best_ask_index) = eai
        report "ask_index mismatch at op " & integer'image(cycles) severity failure;
      assert to_integer(best_ask_shares) = eas
        report "ask_shares mismatch at op " & integer'image(cycles) severity failure;
      assert (err_underflow_clamped = '1') = (eclamp = 1)
        report "clamp mismatch at op " & integer'image(cycles) severity failure;

      cycles := cycles + 1;
    end loop;

    op_valid <= '0';
    file_close(f);
    report "flat_book_tb: PASS cycles=" & integer'image(cycles) &
           " depth=" & integer'image(DEPTH) severity note;
    finish;
  end process;
end architecture sim;

